// Gateway context and the run window, off the webhook.
const w = $('Webhook').first().json;
const h = w.headers || {};
const b = w.body || {};
const payload = { fromDate: b.fromDate, toDate: b.toDate };
if (Array.isArray(b.branchIds) && b.branchIds.length) payload.branchIds = b.branchIds;
if (Array.isArray(b.workItemTypes) && b.workItemTypes.length) payload.workItemTypes = b.workItemTypes;
return { json: {
  correlationId: h['x-correlation-id'] ?? null,
  callbackUrl: h['x-callback-url'] ?? null,
  dryRun: b.dryRun === true,
  // Self-contained demo: tool payloads supplied in the request itself, so no
  // gateway (or laptop) needs to be reachable from wherever n8n runs.
  fixtures: b.fixtures ?? null,
  payload
} };

// Flatten the queue and rank it. Ranking is UNCHANGED from v1:
//   auth   -> priority(1-3) + ageDays * 0.7
//   claims -> valueScore(1-3) + ageDays * 0.7, value scaled to the run's p95
const PRIORITY = { HIGH: 3, MEDIUM: 2, LOW: 1 };
const CLAIM_TYPES = ['CLAIM_VALIDATION','CLAIM_SUBMISSION','CLAIM_RESUBMISSION','RECONCILIATION'];
const now = new Date();

// Source systems label encounters with bed/ER codes; groups are configured OP/IP.
const ENCOUNTER = {
  NO_BED_NO_ER: 'OP', NO_BED_ER: 'OP', DAYCASE_BED_NO_ER: 'OP', DAYCASE_BED_ER: 'IP',
  INPATIENT_BED_NO_ER: 'IP', INPATIENT_BED_ER: 'IP', NATIONALS_SCREENING: 'OP',
  NEW_VISA_SCREENING: 'OP', RENEWAL_VISA_SCREENING: 'OP', HOME: 'OP',
  ASSISTED_LIVING_FACILITY: 'OP', MOBILE_UNIT: 'OP', AMBULANCE_AIR_OR_WATER: 'OP',
  TELEHEALTH: 'OP', OP: 'OP', IP: 'IP',
};
// Department names arrive spelled many ways; groups store a slug. Compare on a
// normalised key so "E. N. T.", "e.n.t." and "department-E.N.T" all agree.
const deptKey = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');


const entities = [];
for (const item of $input.all()) {
  const d = item.json.data?.assignmentUnassignedEntities ?? item.json.assignmentUnassignedEntities ?? [];
  for (const e of d) entities.push(e);
}

const nets = [];
for (const e of entities) {
  if (!CLAIM_TYPES.includes(e.workItemType)) continue;
  for (const w of (e.workItems || [])) nets.push(typeof w.net === 'number' ? w.net : 0);
}
nets.sort((a, b) => a - b);
let ceiling = 1;
if (nets.length >= 5) {
  const c = nets[Math.min(nets.length - 1, Math.floor(nets.length * 0.95))];
  if (c > 0) ceiling = c;
}
const valueScore = (net) =>
  1 + 2 * Math.max(0, Math.min(1, (typeof net === 'number' ? net : 0) / ceiling));

const items = [];
for (const e of entities) {
  const isClaim = CLAIM_TYPES.includes(e.workItemType);
  for (const w of (e.workItems || [])) {
    const start = w.startDate ? new Date(w.startDate) : now;
    const ageDays = Math.max(0, (now - start) / 86400000);
    const base = isClaim ? valueScore(w.net)
                         : (PRIORITY[String(w.priority || '').toUpperCase()] ?? 1);
    items.push({
      id: String(w.id),
      workItemType: e.workItemType,
      branchId: e.branchId,
      facilityId: e.facilityId,
      department: w.department ?? null,
      departmentKey: deptKey(w.department),
      payer: w.insurancePayer ?? null,
      claimStatus: w.claimStatus ?? null,
      encounterType: ENCOUNTER[String(w.encounterType || '').toUpperCase()] ?? null,
      encounterRaw: w.encounterType ?? null,
      priority: w.priority ?? null,
      ageDays: Math.round(ageDays * 10) / 10,
      rank: Math.round((base + ageDays * 0.7) * 100) / 100
    });
  }
}
items.sort((a, b) => b.rank - a.rank);
return [{ json: { items, branchIds: [...new Set(items.map(i => i.branchId).filter(Boolean))] } }];

// v3 matching: routing rules are criteria, not hardcoded axes.
//
// A group accepts an item when every criterion on its effective rule admits it.
// When several accept, the NARROWEST wins, scored by how few values each
// dimension admits. See CRITERIA-CONTRACT.md for the normative semantics; the
// functions below mirror allocation-model.ts and must agree with it row for row.
//
// Dual input by design. Groups carrying `criteria` use them directly; groups
// still in the v2 shape (workItemTypes/departments/payers/...) are adapted into
// criteria first, so this node runs against today's T-0002 and against the
// updated gateway component without a flag day.

/* ── registry ──────────────────────────────────────────────────────────────
   Defaults mirror DIMENSIONS in allocation-model.ts. When T-0002 starts
   returning allocationDimensions, the payload wins and this becomes a
   fallback, which is what makes a new axis a row rather than an edit. */
/**
 * Aliases, normalised on both sides, carried by the dimension rather than by
 * the matcher. Derived from v1's 42-entry deptTagMap: 30 of those entries are
 * pure punctuation and case, which normalisation already handles, leaving
 * these 12 genuine synonyms. Dropping them was a silent regression from v1,
 * because normalisation cannot unify a misspelling with its correct spelling.
 *
 * "dermatology" maps to the misspelled "dermatalogy" deliberately: that is the
 * spelling the production team tags use, so it is the canonical one.
 */
const DEPARTMENT_ALIASES = {
  cardiologyservices: 'cardiology',
  dermatology: 'dermatalogy',
  nutrition: 'dieticiannutrition',
  dietician: 'dieticiannutrition',
  gihconcology: 'oncology',
  hematology: 'oncology',
  intensivecareuniticu: 'icu',
  dramrelshawarbineurosurgerycenter: 'neurosurgery',
  obstetricsgynaeivf: 'obstetricsgyneivf',
  optics: 'optimetry',
  pediatrics: 'pediatricsneonatology',
  podiatrics: 'podiatry',
};

const DEFAULT_DIMENSIONS = [
  { code: 'FACILITY',       itemField: 'facilityId',     matchMode: 'EXACT',      sortOrder: 10 },
  { code: 'WORK_ITEM_TYPE', itemField: 'workItemType',   matchMode: 'EXACT',      sortOrder: 20 },
  { code: 'ENCOUNTER_TYPE', itemField: 'encounterType',  matchMode: 'EXACT',      sortOrder: 30 },
  { code: 'DEPARTMENT',     itemField: 'department',     matchMode: 'NORMALISED', sortOrder: 40,
    aliases: DEPARTMENT_ALIASES },
  { code: 'PAYER',          itemField: 'payer',          matchMode: 'EXACT',      sortOrder: 50 },
  { code: 'CLAIM_STATUS',   itemField: 'claimStatus',    matchMode: 'EXACT',      sortOrder: 60 },
];

const ranked = $('Rank Items').first().json.items;
const raw = $('Step 1 - Get Teams').first().json;
const teams = raw.data?.optimaTeams ?? raw.optimaTeams ?? [];
const servedDimensions = raw.data?.allocationDimensions ?? raw.allocationDimensions;

/** GraphQL serves aliases as {from,to} rows; the matcher indexes a map. */
const asAliasMap = (a) =>
  Array.isArray(a) ? Object.fromEntries(a.map((r) => [r.from, r.to])) : (a ?? {});

const dimensions = (servedDimensions ?? DEFAULT_DIMENSIONS).map((d) => ({
  ...d,
  aliases: asAliasMap(d.aliases),
}));
const dimByCode = Object.fromEntries(dimensions.map((d) => [d.code, d]));

/* ── matcher, ported from allocation-model.ts ──────────────────────────── */

/** Lowercase alphanumerics. "E. N. T.", "e.n.t" and "ENT" all agree. */
const normKey = (s) => String(s ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');

/**
 * Normalised comparison also drops a leading dimension-code prefix, because
 * three spellings of the same department are all live right now: v1 team tags
 * say "department-emergency", the v2 fixtures say "dental-and-maxillofacial",
 * and the work queue says "Emergency". Stripping the prefix makes all three
 * agree instead of forcing a data migration before anything matches.
 * Only stripped when something is left over, so a department actually named
 * after its dimension does not normalise away to nothing.
 */
function normValue(dim, v) {
  const k = normKey(v);
  const prefix = normKey(dim?.code);
  const stripped = prefix && k.startsWith(prefix) && k.length > prefix.length ? k.slice(prefix.length) : k;
  // Synonyms last, so an alias written either with or without the prefix
  // resolves the same way.
  return dim?.aliases?.[stripped] ?? stripped;
}

const keyFor = (dim, v) => (dim?.matchMode === 'NORMALISED' ? normValue(dim, v) : String(v ?? ''));

/**
 * Does one criterion admit this item?
 *
 * The asymmetry on a missing value is deliberate and is the one place this
 * differs from the v2 node: IN is a positive claim and needs evidence, so a
 * missing value rejects; NOT_IN is an exclusion and absence cannot prove
 * membership, so a missing value passes.
 */
function criterionAccepts(c, item) {
  if (c.operator === 'ANY') return true;
  const dim = dimByCode[c.dimension];
  if (!dim) return true;
  const rawVal = item[dim.itemField];
  const present = rawVal != null && String(rawVal) !== '';
  const set = new Set((c.values ?? []).map((v) => keyFor(dim, v)));

  if (c.operator === 'NOT_IN') return !present || !set.has(keyFor(dim, rawVal));
  if (!present) return false;
  return set.has(keyFor(dim, rawVal));
}

const criteriaAccept = (criteria, item) => (criteria ?? []).every((c) => criterionAccepts(c, item));

/** The first criterion that rejects, so "why was this not allocated" is answerable. */
function rejectingCriterion(criteria, item) {
  for (const c of criteria ?? []) if (!criterionAccepts(c, item)) return c;
  return null;
}

/**
 * How narrow a rule is. Constraining more dimensions always beats constraining
 * fewer, so the count leads; within that, naming one value beats naming six.
 */
function specificityOf(criteria) {
  let constrained = 0;
  let narrowness = 0;
  for (const c of criteria ?? []) {
    if (c.operator === 'ANY' || !(c.values ?? []).length) continue;
    constrained += 1;
    narrowness += c.operator === 'NOT_IN' ? 1 : Math.floor(100 / c.values.length);
  }
  return constrained * 1000 + narrowness;
}

/** A group inherits its team's rule and narrows it. Same dimension, group wins. */
function mergeCriteria(team = [], group = []) {
  const out = new Map();
  for (const c of team) out.set(c.dimension, c);
  for (const c of group) out.set(c.dimension, c);
  return [...out.values()];
}

/* ── v2 shape adapter ──────────────────────────────────────────────────────
   Turns the legacy named fields into criteria so there is exactly one matcher
   rather than two code paths. Drops out entirely once T-0002 returns criteria. */
function criteriaFromLegacy(team, g) {
  const out = [];
  const push = (dimension, operator, values) => out.push({ dimension, operator, values });

  if ((g.workItemTypes ?? []).length) push('WORK_ITEM_TYPE', 'IN', g.workItemTypes);

  const scope = g.encounterScope ?? team.encounterScope;
  if (scope && scope !== 'BOTH') push('ENCOUNTER_TYPE', 'IN', [scope]);

  if (team.logicAxis === 'PAYER') {
    if (g.payerCatchAll) push('PAYER', 'ANY', []);
    else if ((g.payers ?? []).length) push('PAYER', 'IN', g.payers.map(String));
  } else if ((g.departments ?? []).length) {
    push('DEPARTMENT', 'IN', g.departments);
  }

  if ((g.claimStatuses ?? []).length) push('CLAIM_STATUS', 'IN', g.claimStatuses);
  return out;
}

/** The rule the matcher actually runs for this group. */
function effectiveCriteriaOf(team, g) {
  if ((g.effectiveCriteria ?? []).length) return g.effectiveCriteria;
  if ((g.criteria ?? []).length || (team.criteria ?? []).length) {
    return mergeCriteria(team.criteria, g.criteria);
  }
  return criteriaFromLegacy(team, g);
}

/**
 * Facility gate. A branch may carry several health licences since OPTIMA-4657,
 * so this is a membership test over a list, not an equality check.
 */
function servesFacility(team, item) {
  const branches = team.branches ?? [];
  if (!branches.length) return true;
  return branches.some((b) => {
    const licences = b.healthLicenses ?? (b.healthLicense != null ? [b.healthLicense] : []);
    return licences.some((l) => String(l) === String(item.facilityId));
  }) || String(team.branchId ?? '') === String(item.branchId);
}

/**
 * Members who can actually be given work tonight.
 *
 * Somebody on leave is still a member of the group, so they come back from
 * T-0002; they just cannot take anything. Filtering here rather than in
 * Distribute keeps them out of `userIds` too, so T-0003 and T-004 are not
 * asked for the capacity of people who are away.
 *
 * Absent field means available: an older T-0002 that does not select
 * unavailableToday must not silently empty every pool.
 */
const availableMembers = (g) =>
  (g.members ?? []).filter((m) => m.unavailableToday !== true);

/* ── match ─────────────────────────────────────────────────────────────── */

const assignments = [];
const unmatched = [];
const memberIds = new Set();

for (const item of ranked) {
  const candidates = [];
  let nearest = null;

  for (const t of teams) {
    if (!servesFacility(t, item)) continue;
    for (const g of t.groups ?? []) {
      if (g.active === false) continue;
      const eff = effectiveCriteriaOf(t, g);
      if (criteriaAccept(eff, item)) {
        candidates.push({ team: t, group: g, eff, spec: specificityOf(eff) });
      } else if (!nearest) {
        const c = rejectingCriterion(eff, item);
        nearest = { group: g.name, dimension: c?.dimension ?? null };
      }
    }
  }

  if (!candidates.length) {
    unmatched.push({
      id: item.id,
      workItemType: item.workItemType,
      department: item.department,
      payer: item.payer,
      reason: nearest
        ? `No group accepts this item (nearest '${nearest.group}' rejected on ${nearest.dimension})`
        : 'No group accepts this item',
      rejectedOn: nearest?.dimension ?? null,
    });
    continue;
  }

  // Narrowest wins. Ties resolve on group id so a rerun of the same input
  // allocates the same way; array order is insertion order and is not stable.
  candidates.sort((a, b) => b.spec - a.spec || String(a.group.id).localeCompare(String(b.group.id)));
  const best = candidates[0];
  const members = availableMembers(best.group).map((m) => String(m.id ?? m.userId));
  members.forEach((m) => memberIds.add(m));

  assignments.push({
    ...item,
    teamId: best.team.id,
    teamName: best.team.name,
    groupId: best.group.id,
    groupName: best.group.name,
    groupMembers: members,
    // Total roster vs who can actually take work today. Distribute needs both
    // to tell "nobody is in this group" from "everybody in it is on leave",
    // which send a supervisor to two different places.
    groupRoster: (best.group.members ?? []).length,
    // Every group that accepted, narrowest first, so Distribute can fall
    // through to the next one when the winner has no capacity left.
    groupFallbacks: candidates.slice(1).map((c) => {
      const ids = availableMembers(c.group).map((m) => String(m.id ?? m.userId));
      // Fallback members need capacity fetched too, or Distribute reads them
      // as zero and the fallback can never fire.
      ids.forEach((m) => memberIds.add(m));
      return { groupId: c.group.id, groupName: c.group.name, teamId: c.team.id, members: ids };
    }),
  });
}

return [{
  json: {
    assignments,
    unmatched,
    userIds: [...memberIds],
    teamId: assignments[0]?.teamId ?? null,
    workItemTypes: [...new Set(assignments.map((a) => a.workItemType))],
  },
}];

// Spread each group's matched items across that group's members.
//
// Three rules, in order:
//   1. Highest-ranked item first.
//   2. To the least *utilised* eligible member, not the least loaded. A member
//      capped at 200 and one capped at 50 both sitting on 20 items are not
//      equally busy, and sorting on the raw count starves the bigger cap.
//   3. When the winning group has no capacity left, fall through to the next
//      narrowest group that also accepted the item, rather than stranding work
//      next to idle people. Match Groups supplies those in `groupFallbacks`.

const matched = $('Match Groups').first().json;
const kpiRaw = $('Step 2 - Assigned Counts').first().json;
const capRaw = $('Step 3 - Capacities').first().json;

const counts = kpiRaw.data?.usersWorkTypeAssignedCounts ?? kpiRaw.usersWorkTypeAssignedCounts ?? [];
const caps = capRaw.data?.effectiveAssignmentSettings ?? capRaw.effectiveAssignmentSettings ?? [];

const AUTH = ['AUTHORIZATION_SUBMISSION', 'AUTHORIZATION_RESUBMISSION'];

const assignedBy = {};
for (const c of counts) {
  const uid = String(c.userId);
  assignedBy[uid] = (assignedBy[uid] ?? 0) + (c.assigned ?? 0);
}

/**
 * Capacities come back one row per (user, team) when teamId is null, so a
 * member of several teams appears more than once. Take the LOWEST cap: the
 * caps are per-team commitments and honouring the smallest is the only choice
 * that cannot overcommit someone. Keyed assignment would silently let row
 * order decide.
 */
const state = {};
for (const c of caps) {
  const uid = String(c.userId);
  const maxAuth = c.maxAuth ?? 0;
  const maxClaim = c.maxClaim ?? 0;
  if (!state[uid]) {
    state[uid] = { maxAuth, maxClaim, used: assignedBy[uid] ?? 0, teams: 1 };
  } else {
    state[uid].maxAuth = Math.min(state[uid].maxAuth, maxAuth);
    state[uid].maxClaim = Math.min(state[uid].maxClaim, maxClaim);
    state[uid].teams += 1;
  }
}

const capOf = (uid, wit) => {
  const r = state[uid];
  if (!r) return 0;
  return AUTH.includes(wit) ? r.maxAuth : r.maxClaim;
};
const capLeft = (uid, wit) => Math.max(0, capOf(uid, wit) - (state[uid]?.used ?? 0));

/** Fraction of this member's cap already consumed. Unknown cap sorts last. */
const utilisation = (uid, wit) => {
  const cap = capOf(uid, wit);
  if (!cap) return Infinity;
  return (state[uid]?.used ?? 0) / cap;
};

/** Eligible members of one group, least utilised first. */
function poolFor(memberIds, wit) {
  return (memberIds ?? [])
    .filter((uid) => capLeft(uid, wit) > 0)
    .sort((a, b) => utilisation(a, wit) - utilisation(b, wit) || String(a).localeCompare(String(b)));
}

const perAssignee = {};
const overflow = [];
const fallbackUsed = [];

for (const item of matched.assignments) {
  // The winning group first, then every other group that accepted, narrowest
  // first. Identical to the old behaviour whenever the winner has room.
  const tiers = [
    { groupId: item.groupId, groupName: item.groupName, teamId: item.teamId, members: item.groupMembers },
    ...(item.groupFallbacks ?? []),
  ];

  let placed = null;
  for (let i = 0; i < tiers.length; i += 1) {
    const pool = poolFor(tiers[i].members, item.workItemType);
    if (!pool.length) continue;
    placed = { tier: tiers[i], uid: pool[0], depth: i };
    break;
  }

  if (!placed) {
    overflow.push({
      id: item.id,
      groupName: item.groupName,
      triedGroups: tiers.length,
      reason: (item.groupMembers ?? []).length
        ? `No capacity in ${tiers.length} accepting group(s)`
        : item.groupRoster
          ? `All ${item.groupRoster} member(s) of the group are unavailable today`
          : 'Group has no members',
    });
    continue;
  }

  const { tier, uid, depth } = placed;
  state[uid].used += 1;
  if (depth > 0) {
    fallbackUsed.push({ id: item.id, from: item.groupName, to: tier.groupName, depth });
  }

  const key = `${uid}|${item.workItemType}`;
  if (!perAssignee[key]) {
    perAssignee[key] = {
      assigneeId: uid,
      workItemType: item.workItemType,
      teamId: tier.teamId,
      groupName: tier.groupName,
      workItemIds: [],
    };
  }
  perAssignee[key].workItemIds.push(item.id);
}

const batches = Object.values(perAssignee);
const dryRun = $('extractInfo').first().json.dryRun;
const multiTeam = Object.values(state).filter((r) => r.teams > 1).length;

if (!batches.length) {
  return [{ json: {
    skipped: true,
    reason: 'No capacity anywhere',
    overflowCount: overflow.length,
    overflow,
    dryRun,
    workItemIds: [],
    assigneeId: null,
  } }];
}

return batches.map((b, i) => ({ json: {
  ...b,
  itemCount: b.workItemIds.length,
  overflowCount: overflow.length,
  fallbackCount: fallbackUsed.length,
  multiTeamMembers: multiTeam,
  // The detail rides on the first batch only, so Summarise can report why work
  // was not placed without every batch repeating the same list. Previously
  // these were returned only when nothing at all could be assigned, so a run
  // that placed most of its work reported a count with no reasons behind it.
  overflow: i === 0 ? overflow : [],
  fallback: i === 0 ? fallbackUsed : [],
  dryRun,
} }));

// Roll the run into one allocation summary.
let batches = [];
try { batches = $('Distribute').all().map(i => i.json).filter(b => !b.skipped); } catch (e) {}
let results = [];
try { results = $('Step 4 - Assign').all().map(i => i.json); } catch (e) {}

const matched = $('Match Groups').first().json;
const dryRun = $('extractInfo').first().json.dryRun;

const byGroup = {};
for (const a of (matched.assignments || [])) {
  if (!byGroup[a.groupName]) byGroup[a.groupName] = { group: a.groupName, team: a.teamName, matched: 0 };
  byGroup[a.groupName].matched += 1;
}
const assigned = batches.reduce((n, b) => n + (b.workItemIds?.length ?? 0), 0);

return [{ json: {
  correlationId: $('extractInfo').first().json.correlationId,
  model: 'v2-groups',
  dryRun,
  totals: {
    ranked: $('Rank Items').first().json.items.length,
    matched: (matched.assignments || []).length,
    assigned,
    unmatched: (matched.unmatched || []).length,
    overflow: batches[0]?.overflowCount ?? 0
  },
  byGroup: Object.values(byGroup),
  byAssignee: batches.map(b => ({ assigneeId: b.assigneeId, group: b.groupName,
                                  workItemType: b.workItemType, count: b.workItemIds.length })),
  unmatchedSample: (matched.unmatched || []).slice(0, 20),
  apiResults: results.map(r => r.data?.assignWorkItems ?? r.assignWorkItems ?? r)
} }];

return [{ json: {
  correlationId: $('extractInfo').first().json.correlationId,
  model: 'v2-groups',
  totals: { ranked: 0, matched: 0, assigned: 0, unmatched: 0, overflow: 0 },
  message: 'No unassigned work in the requested window'
} }];

// Return the supplied fixture in place of the tool response.
const fx = $('extractInfo').first().json.fixtures;
return [{ json: { data: { assignmentUnassignedEntities: fx['assignmentUnassignedEntities'] } } }];

// Return the supplied fixture in place of the tool response.
// allocationDimensions rides along so fixture mode exercises the served
// registry rather than silently falling back to the node's own defaults.
const fx = $('extractInfo').first().json.fixtures;
return [{ json: { data: {
  optimaTeams: fx['optimaTeams'],
  allocationDimensions: fx['allocationDimensions'] ?? null,
} } }];

// Return the supplied fixture in place of the tool response.
const fx = $('extractInfo').first().json.fixtures;
return [{ json: { data: { usersWorkTypeAssignedCounts: fx['usersWorkTypeAssignedCounts'] } } }];

// Return the supplied fixture in place of the tool response.
const fx = $('extractInfo').first().json.fixtures;
return [{ json: { data: { effectiveAssignmentSettings: fx['effectiveAssignmentSettings'] } } }];
